import { CARD_YEARS } from '../config/defaults.js';

/** Tells whether a member's library card has expired by `today`. */
export function isCardExpired(member, today) {
  return member.cardExpiresOn < today;
}

/** Returns the member with their card renewed from today for the years their type allows. */
export function renewCard(member, today) {
  const year = Number(today.slice(0, 4)) + CARD_YEARS[member.type];
  return { ...member, cardExpiresOn: `${year}${today.slice(4)}` };
}
/** Lower-cases text and turns every run of punctuation and spaces into one space, for matching. */
export function normaliseText(text) {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Replaces each {name} in a template by the value of that name; unknown names stay as they are. */
export function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    name in values ? String(values[name]) : placeholder,
  );
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { handleCheckoutMessage, parseCheckoutRequest } from '../lib/selfcheck/sip2.js';
import { ADA, BOOK, sampleStore, TODAY } from './sample-library.js';

test('reads the card number and the barcode of a checkout request', () => {
  assert.deepEqual(parseCheckoutRequest(`11|AA${ADA.cardNumber}|AB${BOOK.barcode}|`), {
    cardNumber: ADA.cardNumber,
    barcode: BOOK.barcode,
  });
});

test('lends the item and replies with its due date', () => {
  const store = sampleStore();
  const reply = handleCheckoutMessage(store, `11|AA${ADA.cardNumber}|AB${BOOK.barcode}|`, TODAY);
  assert.equal(reply, `121|AB${BOOK.id}|AH12/17/2026|`);
  assert.equal(store.findOpenLoan(BOOK.id).memberId, ADA.id);
});

test('refuses a card nobody holds', () => {
  const reply = handleCheckoutMessage(sampleStore(), `11|AA29999999999999|AB${BOOK.barcode}|`, TODAY);
  assert.equal(reply, '120|AFunknown-member|');
});

test('refuses a message that is not a checkout request', () => {
  assert.throws(() => parseCheckoutRequest('93|CNdesk|'), /Not a checkout request/);
});
